struct block_device *get_block_device(dev_t dev, struct super_block *sb) {
    struct block_device *bdev = NULL;
    int flags = FMODE_READ | FMODE_WRITE | FMODE_EXCL;

    bdev = bdget(dev);
    if (!bdev) {
        printk(KERN_ERR "Failed to get block device for dev %u:%u\n",
               MAJOR(dev), MINOR(dev));
        return NULL;
    }

    if (bdev->bd_openers) {
        bdput(bdev);
        return NULL;
    }

    if (sb) {
        sb->s_bdev = bdev;
        sb->s_flags |= SB_BDEV;
    }

    return bdev;
}

