    int mode = FMODE_READ | FMODE_WRITE | FMODE_EXCL;

    bdev = open_bdev_exclusive(dev, mode, sb);
    if (IS_ERR(bdev)) {
        printk(KERN_ERR "Failed to open block device for dev %d:%d\n",
               MAJOR(dev), MINOR(dev));
        return NULL;
    }

    return bdev;
}

